/**
 * The typed tables of the contract model, generated by IFC Data from the model. Do not edit: change the model and run `bun tools/typed.ts --write`.
 *
 * What a dataset promises, when the promises hold, and the proof that they are kept
 *
 * @module
 */
import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** What a dataset promises to those who read it, in one version: its owner, its status and the dates between which the version holds; its fields are the fields of the contract */
export interface DataContractRow {
  /** What identifies the contract: its dataset and version */
  readonly dataContractId: string;
  /** The dataset it is of */
  readonly dataset: string;
  /** The version of the contract, as major.minor.patch */
  readonly version: string;
  /** Where it is */
  readonly status: "draft" | "active" | "deprecated" | "retired";
  /** Who answers for it */
  readonly owner: string;
  /** From when it holds */
  readonly validFrom: Timestamp;
  /** Until when it holds, where it ends */
  readonly validTo: Timestamp | null;
}

/** What an insert into data_contract takes: what the database fills may be left out. */
export interface DataContractInsert {
  readonly dataContractId: string;
  readonly dataset: string;
  readonly version: string;
  readonly status: "draft" | "active" | "deprecated" | "retired";
  readonly owner: string;
  readonly validFrom: Timestamp;
  readonly validTo?: Timestamp | null;
}

/** The key of a row of data_contract. */
export type DataContractKey = { readonly dataContractId: string };

/** What a dataset promises to those who read it, in one version: its owner, its status and the dates between which the version holds; its fields are the fields of the contract */
export const dataContract = defineTable<DataContractRow, DataContractInsert, "dataContract">({
  alias: "dataContract",
  name: "data_contract",
  columns: {
    dataContractId: "data_contract_id",
    dataset: "dataset",
    version: "version",
    status: "status",
    owner: "owner",
    validFrom: "valid_from",
    validTo: "valid_to",
  },
  primaryKey: ["dataContractId"],
});

/** One field a data contract promises: its name, its datatype, whether it may be missing and how it is classified */
export interface ContractFieldRow {
  /** What identifies the field: its contract and name */
  readonly contractFieldId: string;
  /** The name of the field */
  readonly fieldName: string;
  /** The datatype, as the contract names it */
  readonly datatype: string;
  /** Whether it may be missing */
  readonly nullable: boolean;
  /** How sensitive it is: public, internal, confidential or restricted */
  readonly classification: string | null;
  /** The contract it is a field of */
  readonly contractDataContractId: string;
}

/** What an insert into contract_field takes: what the database fills may be left out. */
export interface ContractFieldInsert {
  readonly contractFieldId: string;
  readonly fieldName: string;
  readonly datatype: string;
  readonly nullable: boolean;
  readonly classification?: string | null;
  readonly contractDataContractId: string;
}

/** The key of a row of contract_field. */
export type ContractFieldKey = { readonly contractFieldId: string };

/** One field a data contract promises: its name, its datatype, whether it may be missing and how it is classified */
export const contractField = defineTable<ContractFieldRow, ContractFieldInsert, "contractField">({
  alias: "contractField",
  name: "contract_field",
  columns: {
    contractFieldId: "contract_field_id",
    fieldName: "field_name",
    datatype: "datatype",
    nullable: "nullable",
    classification: "classification",
    contractDataContractId: "contract_data_contract_id",
  },
  primaryKey: ["contractFieldId"],
  foreignKeys: [
    { columns: ["contractDataContractId"], references: "dataContract", referencesColumns: ["dataContractId"] },
  ],
});

/** A span of time of one scope (a month of a ledger, a reporting quarter) that takes changes while it is open and is closed when its figures are final */
export interface PeriodRow {
  /** What identifies the period: its scope and span */
  readonly periodId: string;
  /** What it is a period of */
  readonly scope: string;
  /** Where it starts */
  readonly startsOn: Timestamp;
  /** Where it ends, not included */
  readonly endsOn: Timestamp;
  /** Whether it takes changes */
  readonly status: "open" | "closed" | "reopened";
  /** Who closed it */
  readonly closedBy: string | null;
  /** When it was closed */
  readonly closedAt: Timestamp | null;
  /** Why it was opened again, where it was */
  readonly reason: string | null;
}

/** What an insert into period takes: what the database fills may be left out. */
export interface PeriodInsert {
  readonly periodId: string;
  readonly scope: string;
  readonly startsOn: Timestamp;
  readonly endsOn: Timestamp;
  readonly status: "open" | "closed" | "reopened";
  readonly closedBy?: string | null;
  readonly closedAt?: Timestamp | null;
  readonly reason?: string | null;
}

/** The key of a row of period. */
export type PeriodKey = { readonly periodId: string };

/** A span of time of one scope (a month of a ledger, a reporting quarter) that takes changes while it is open and is closed when its figures are final */
export const period = defineTable<PeriodRow, PeriodInsert, "period">({
  alias: "period",
  name: "period",
  columns: {
    periodId: "period_id",
    scope: "scope",
    startsOn: "starts_on",
    endsOn: "ends_on",
    status: "status",
    closedBy: "closed_by",
    closedAt: "closed_at",
    reason: "reason",
  },
  primaryKey: ["periodId"],
});

/** A control: what must hold, who answers for it, how often it is checked and the test or evidence that checks it, one row of the control matrix */
export interface ControlRow {
  /** What identifies the control */
  readonly controlId: string;
  /** What must hold */
  readonly objective: string;
  /** Who answers for it */
  readonly owner: string;
  /** How often it is checked, as a number of days */
  readonly frequency: string;
  /** The test, spec or report that checks it */
  readonly evidenceRef: string;
  /** The framework or rule it answers to, where one */
  readonly framework: string | null;
}

/** What an insert into control takes: what the database fills may be left out. */
export interface ControlInsert {
  readonly controlId: string;
  readonly objective: string;
  readonly owner: string;
  readonly frequency: string;
  readonly evidenceRef: string;
  readonly framework?: string | null;
}

/** The key of a row of control. */
export type ControlKey = { readonly controlId: string };

/** A control: what must hold, who answers for it, how often it is checked and the test or evidence that checks it, one row of the control matrix */
export const control = defineTable<ControlRow, ControlInsert, "control">({
  alias: "control",
  name: "control",
  columns: {
    controlId: "control_id",
    objective: "objective",
    owner: "owner",
    frequency: "frequency",
    evidenceRef: "evidence_ref",
    framework: "framework",
  },
  primaryKey: ["controlId"],
});

/** What one run of a control found and when, with the evidence of it: a row of the history of a control, only added to */
export interface ControlRunRow {
  /** What identifies the run */
  readonly controlRunId: string;
  /** What it found */
  readonly result: "pass" | "fail" | "waived" | "not_run";
  /** When */
  readonly ranAt: Timestamp;
  /** Where the evidence is kept */
  readonly evidence: string | null;
  /** The control that was run */
  readonly controlId: string;
}

/** What an insert into control_run takes: what the database fills may be left out. */
export interface ControlRunInsert {
  readonly controlRunId: string;
  readonly result: "pass" | "fail" | "waived" | "not_run";
  readonly ranAt: Timestamp;
  readonly evidence?: string | null;
  readonly controlId: string;
}

/** The key of a row of control_run. */
export type ControlRunKey = { readonly controlRunId: string };

/** What one run of a control found and when, with the evidence of it: a row of the history of a control, only added to */
export const controlRun = defineTable<ControlRunRow, ControlRunInsert, "controlRun">({
  alias: "controlRun",
  name: "control_run",
  columns: {
    controlRunId: "control_run_id",
    result: "result",
    ranAt: "ran_at",
    evidence: "evidence",
    controlId: "control_id",
  },
  primaryKey: ["controlRunId"],
  foreignKeys: [
    { columns: ["controlId"], references: "control", referencesColumns: ["controlId"] },
  ],
});

